import math
    import random
    import time

    LANGUAGE_WRAPPER = 'A rectangular grid maze has {rows} rows and {cols} columns of unit squares. For each middle row (that is, rows 2 through {rows_minus_two_plus_one}), there is exactly one invisible teleportation gate hidden in that row, and no two gates lie in the same column. An explorer may start each attempt from any chosen square in the top row. In an attempt, the explorer may move one square at a time up, down, left, or right, revisiting squares if desired. If the explorer steps on a teleportation gate, the attempt immediately ends and the explorer is returned to the starting square of that attempt; the exact gate location just triggered is then recorded and remembered for future attempts. If the explorer reaches any square in the bottom row, they immediately succeed and the process stops. Give a general strategy that guarantees success in the worst case by the k-th attempt, no matter how the gates are placed subject to the rules, and find the minimum possible value of k in terms of {rows} and {cols}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose rows >= 5 so there are nontrivial middle rows
# We keep the tight setting cols = rows - 1, which is the extremal AIME-like regime
# where the injection row->column is possible but leaves no slack columns.
while True:
    r = rng.randint(5, 2001)
    c = r - 1
    if r >= 3 and c >= 2:
        return {
            'rows': r,
            'cols': c,
            'rows_minus_two_plus_one': r - 1
        }

    def verifier(assign):
# Validate inputs
rows = assign.get('rows', None)
cols = assign.get('cols', None)
rmp = assign.get('rows_minus_two_plus_one', None)
if not isinstance(rows, int) or not isinstance(cols, int) or not isinstance(rmp, int):
    # invalid types
    return (False, None)
if rows < 3 or cols < 2:
    # too small
    return (False, None)
if cols != rows - 1:
    # must be the tight case
    return (False, None)
if rmp != rows - 1:
    # mismatch in placeholder
    return (False, None)
# In this tight regime (exactly one gate per middle row, no two gates share a column, and cols = rows - 1),
# the optimal worst-case number of attempts is always 3.
# Sketch justification (formal proof is in problem's solution writeup):
# 1) Lower bound: There exists an adversarial placement that forces failure on the first two attempts
#    for any strategy, by aligning the unique gate per row to meet the explorer's first two chosen traversals.
# 2) Upper bound: A universal 3-attempt strategy proceeds by two carefully designed sweeping paths that
#    identify a structured set of gate positions; the third pass then threads a bottom-reaching route that
#    systematically avoids the learned columns (possible due to injectivity across rows and tight column count).
answer = 3
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

